    const mmat = new THREE.ShaderMaterial({ uniforms: { map: { value: mtex }, uTime: { value: 0 }, uFogD: { value: 0.001 } }, vertexShader: HOLO_V, fragmentShader: HOLO_F, transparent: true, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide });
    P.martini = IPool('martini', new THREE.PlaneGeometry(1, 1), mmat, 8, { aSeed: 1 });
    P.holo.push(P.martini);

    // searchlight beams (pooled meshes, sweep each frame)
    const bg = new THREE.CylinderGeometry(1.5, 22, 720, 12, 1, true); bg.translate(0, 360, 0);
    const bm = [new THREE.MeshBasicMaterial({ color: new THREE.Color(0.55, 0.62, 0.62), transparent: true, opacity: 0.075, blending: THREE.AdditiveBlending, depthWrite: false, fog: false, side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ color: new THREE.Color(0.75, 0.55, 0.3), transparent: true, opacity: 0.07, blending: THREE.AdditiveBlending, depthWrite: false, fog: false, side: THREE.DoubleSide })];
    for (let i = 0; i < 9; i++) { const b = new THREE.Mesh(bg, bm[i % 2]); b.visible = false; b.frustumCulled = false; b.userData = { key: -1e9, ph: 0, sp: 0.3, ax: 0.4, rx: 0, rz: 0 }; root.add(b); beams.push(b); }

