    const pm = facadeMat(true), tiers = TIERS, TH = TIER_H, pyrMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), pm, tiers + 2);
    const gpa = pyrMesh.geometry; const st = new Float32Array((tiers + 2) * 4), bs = new Float32Array((tiers + 2) * 3), sd = new Float32Array(tiers + 2);
    for (let i = 0; i < tiers; i++) {
      const k = 1 - i * 0.064, w = 1150 * k, d = 800 * k, h = TH;
      _m.makeScale(w, h, d).setPosition(0, GY + h / 2 + i * h, 0); pyrMesh.setMatrixAt(i, _m);
      st.set([0.46, 0, 1.4, 4], i * 4); bs.set(lin(0x1c1813), i * 3); sd[i] = i * 0.37;
    }
    const topY = GY + tiers * TH;
    _m.makeScale(120, 90, 120).setPosition(0, topY + 45, 0); pyrMesh.setMatrixAt(tiers, _m); st.set([0.6, 1, 1, 0], tiers * 4); bs.set(lin(0x1a1a1c), tiers * 3); sd[tiers] = 7.1;
    _m.makeScale(36, 220, 36).setPosition(0, topY + 110, 0); pyrMesh.setMatrixAt(tiers + 1, _m); st.set([0.25, 1, 1, 0], (tiers + 1) * 4); bs.set(lin(0x101012), (tiers + 1) * 3); sd[tiers + 1] = 3.3;
    gpa.setAttribute('aStyle', new THREE.InstancedBufferAttribute(st, 4)); gpa.setAttribute('aBase', new THREE.InstancedBufferAttribute(bs, 3)); gpa.setAttribute('aSeed', new THREE.InstancedBufferAttribute(sd, 1));
    pyrMesh.frustumCulled = false; pyr.add(pyrMesh); pyr.userData.mat = pm;
