    sky.position.copy(cam.position); pano.position.set(cam.position.x, GY + 40 + 0, cam.position.z);
    pano.position.y = GY; // band horizon sits at ground level far away
    const su = sky.material.uniforms;
    lerpHex(su.a.value, A.sky[0], B.sky[0], b.t); lerpHex(su.b.value, A.sky[1], B.sky[1], b.t); su.fc.value.copy(scene.fog ? scene.fog.color : su.b.value);
    flashSky = Math.max(0, flashSky - dt * 5); su.fl.value = flashSky;
    const pu = pano.material.uniforms;
    pu.tA.value = panoTex[b.a]; pu.tB.value = panoTex[b.b]; pu.hA.value = panoHor[b.a]; pu.hB.value = panoHor[b.b]; pu.t.value = b.t;
    pu.fc.value.copy(su.fc.value); pu.fl.value = flashSky; pu.gain.value = 0.9 + 0.5 * weightOf(DUST);
    ground.position.set(cam.position.x, GY, cam.position.z - 1500); lerpHex(ground.material.color, A.ground, B.ground, b.t).multiplyScalar(1 + 1.2 * weightOf(DUST));
