    for (let k = 0; k < beams.length; k++) { const bm = beams[k]; if (!bm.visible) continue; const u = bm.userData; bm.rotation.set(u.rx + Math.sin(t * u.sp + u.ph) * u.ax * 0.5, 0, u.rz + Math.sin(t * u.sp * 0.8 + u.ph * 1.3) * u.ax); }
