      try { const gl = c.renderer.getContext(); const r = gl.getParameter(gl.ALIASED_POINT_SIZE_RANGE); const mx = Math.min(512, r[1] || 64); P.glow.mesh.material.uniforms.uMax.value = mx; P.steam.mesh.material.uniforms.uMax.value = mx; } catch (e) {}
