    hazardBoxes() { const out = []; for (let i = 0; i < nHB; i++) { const o = i * 6; out.push({ kind: HBK[i], x0: HB[o], x1: HB[o + 1], y0: HB[o + 2], y1: HB[o + 3], z0: travel - HB[o + 5], z1: travel - HB[o + 4] }); } return out; },
